package com.fidecode.biteflow.application.publicmenu;
import com.fidecode.biteflow.application.order.CreateOrderUseCase;import com.fidecode.biteflow.application.order.dto.*;import com.fidecode.biteflow.application.publicmenu.dto.PublicOrderRequest;import com.fidecode.biteflow.domain.store.exception.*;import com.fidecode.biteflow.domain.store.repository.StoreRepository;import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import java.math.BigDecimal;import java.util.*;
@ApplicationScoped public class CreatePublicOrderUseCase{private final StoreRepository stores;private final CreateOrderUseCase createOrder;@Inject public CreatePublicOrderUseCase(StoreRepository stores,CreateOrderUseCase createOrder){this.stores=stores;this.createOrder=createOrder;}public OrderResponse execute(String identifier,PublicOrderRequest r){var store=stores.findByPublicIdentifier(identifier).orElseThrow(()->new StoreNotFoundException(identifier));if(!store.isOpen())throw new StoreClosedException();String address=r.deliveryAddress()!=null?r.deliveryAddress().address():null;var customer=new CreateOrderRequest.CustomerInfo(null,r.customerName(),address,r.customerPhone(),r.deliveryAddress()!=null?r.deliveryAddress().complement():null,r.deliveryAddress()!=null?r.deliveryAddress().reference():null);var items=r.items().stream().map(i->new CreateOrderItemDto(i.productId(),i.quantity(),null,List.of(),List.of())).toList();String service="PICKUP".equalsIgnoreCase(r.serviceType())?"RETIRADA":"ENTREGA";var request=new CreateOrderRequest("DELIVERY",customer,r.paymentMethod(),items,BigDecimal.ZERO,"DELIVERY",r.channel()!=null?r.channel():"CARDAPIO_PROPRIO",service,r.source()!=null?r.source():"WEB",r.cashChangeFor(),r.notes());return createOrder.create(store.getId(),request);}}
